# -*- coding: utf-8 -*-
"""Publish work/<lang> as a new 2.1.0 version to ClawHub.

POST /api/v1/skills  multipart/form-data
  payload : JSON string {slug, displayName, version, changelog, tags, files:[{path,size,sha256,contentType}]}
  files   : repeated binary parts, same order as payload.files[]
"""
import os, io, sys, json, time, hashlib, mimetypes, urllib.request, urllib.error

TOK = open('.token', encoding='utf-8').read().strip()
BASE = 'https://clawhub.ai/api/v1/'
CATEGORIES = ['communication', 'lifestyle']
# _meta.json is generated by the registry on download; skill-card.md is generated by ClawHub
SKIP = {'_meta.json', 'skill-card.md'}

CT = {'.md': 'text/markdown', '.json': 'application/json', '.mjs': 'text/javascript',
      '.jpg': 'image/jpeg', '.jpeg': 'image/jpeg', '.png': 'image/png'}


def ctype(path):
    return CT.get(os.path.splitext(path)[1].lower(),
                  mimetypes.guess_type(path)[0] or 'application/octet-stream')


def api_get(path):
    req = urllib.request.Request(BASE + path)
    req.add_header('Authorization', 'Bearer ' + TOK)
    with urllib.request.urlopen(req, timeout=30) as r:
        return json.loads(r.read().decode('utf-8'))


def collect(d):
    out = []
    for root, dirs, files in os.walk(d):
        dirs.sort()
        for f in sorted(files):
            p = os.path.join(root, f)
            rel = os.path.relpath(p, d).replace('\\', '/')
            if rel in SKIP:
                continue
            out.append(rel)
    return sorted(out)


def build_body(payload, d, paths):
    b = '----wb' + os.urandom(18).hex()
    parts = []

    def head(name, filename, ct):
        h = '--%s\r\nContent-Disposition: form-data; name="%s"' % (b, name)
        if filename is not None:
            h += '; filename="%s"' % filename
        h += '\r\n'
        if ct:
            h += 'Content-Type: %s\r\n' % ct
        return (h + '\r\n').encode('utf-8')

    parts.append(head('payload', None, 'application/json'))
    parts.append(json.dumps(payload, ensure_ascii=False).encode('utf-8'))
    parts.append(b'\r\n')
    for rel in paths:
        with open(os.path.join(d, rel), 'rb') as f:
            data = f.read()
        parts.append(head('files', rel, ctype(rel)))
        parts.append(data)
        parts.append(b'\r\n')
    parts.append(('--%s--\r\n' % b).encode('utf-8'))
    return b, b''.join(parts)


def publish(lang, dry=False):
    from changelog import CHANGELOG
    slug = 'powpow-register-' + lang if lang != 'zh' else 'powpow-register'
    d = os.path.join('work', lang)
    paths = collect(d)
    meta = api_get('skills/' + slug)['skill']
    files = []
    for rel in paths:
        with open(os.path.join(d, rel), 'rb') as f:
            data = f.read()
        files.append({'path': rel, 'size': len(data),
                      'sha256': hashlib.sha256(data).hexdigest(),
                      'contentType': ctype(rel)})
    payload = {
        'slug': slug,
        'displayName': meta['displayName'],
        'version': '2.1.0',
        'changelog': CHANGELOG[lang],
        'acceptLicenseTerms': True,
        'tags': ['latest'],
        'topics': meta.get('topics') or [],
        'categories': CATEGORIES,
        'files': files,
    }
    total = sum(f['size'] for f in files)
    print('%-3s %-22s files=%d bytes=%d tags=%d' % (lang, slug, len(files), total, len(payload['tags'])))
    if dry:
        print('    [dry] displayName:', payload['displayName'][:80])
        print('    [dry] changelog  :', payload['changelog'][:90])
        return None
    boundary, body = build_body(payload, d, paths)
    req = urllib.request.Request(BASE + 'skills', data=body, method='POST')
    req.add_header('Authorization', 'Bearer ' + TOK)
    req.add_header('Content-Type', 'multipart/form-data; boundary=' + boundary)
    try:
        with urllib.request.urlopen(req, timeout=180) as r:
            return r.status, r.read().decode('utf-8', 'replace')[:400]
    except urllib.error.HTTPError as e:
        return e.code, e.read().decode('utf-8', 'replace')[:600]
    except Exception as e:
        return 'ERR', str(e)[:400]


if __name__ == '__main__':
    args = [a for a in sys.argv[1:] if not a.startswith('--')]
    dry = '--dry' in sys.argv
    for lang in args:
        res = publish(lang, dry=dry)
        if res is not None:
            print('    ->', res[0], res[1])
